contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount == 10);
        require(address(this).balance >= amount);
        require(address(c).balance < 2**200);
        require(c.pot() < 2**200);
        require(address(c).balance >= c.pot());

        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        uint cBalBefore = address(c).balance;

        c.play{value: amount}(); if (__ESBMC_reverted()) return;

        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        uint cBalAfter = address(c).balance;

        // Loss: pot and balance both grew by the ticket amount.
        // Win: pot is fully reset and the whole old pot left the contract.
        assert(
            potAfter == potBefore + 10
                ? cBalAfter == cBalBefore + amount
                : (potAfter == 0 && cBalAfter == cBalBefore - potBefore)
        );
    }

    receive() external payable {}
}

